def run(context):
    # Analyzes the context to determine watchlist actions
    symbols = [entry['symbol'] for entry in context if entry['change_1w_pct'] > 0]
    result_context = [{'symbol': entry['symbol'], 'verdict': entry['verdict']} for entry in context]
    action_bucket = [{'symbol': entry['symbol'], 'action': 'watch' if entry['change_1w_pct'] > 0 else 'review'} for entry in context]
    return {
        'symbol_watchlist': symbols,
        'result_context': result_context,
        'action_bucket': action_bucket
    }
